// R1 live-resource accounting (docs/backend-ir.md §Required semantics, the
// same pairing the py reference tier's `assert no_residue` checks): every host
// object acquired must be released by its `undo`, or the lifecycle
// `assert no_residue` fails. The counter is package-wide, so it is per-test
// and cross-test safe: a clean test returns to zero.
var _revlLiveMu sync.Mutex
var _revlLiveHostResources int

func revlHostAcquire() { _revlLiveMu.Lock(); _revlLiveHostResources++; _revlLiveMu.Unlock() }
func revlHostRelease() { _revlLiveMu.Lock(); _revlLiveHostResources--; _revlLiveMu.Unlock() }
func revlHostLive() int {
	_revlLiveMu.Lock()
	defer _revlLiveMu.Unlock()
	return _revlLiveHostResources
}

// A deterministic in-memory stand-in for revl host objects, instrumented so
// scenarios can assert the exact effect/undo order of emitted code.

var _hostMu sync.Mutex
var _hostLog []string

// ---- declared Secret[T] confidentiality (item 421 F6) -----------------
//
// A declared marking registers its value here, at both ends: revlMarkSecret at
// the head of a provide method that declares a Secret[T] parameter (the
// receiver), revlSecretResult around an extern whose declared return was
// Secret[T] (the origin, where the value enters the value world). hostRecord
// then scrubs it out of every trace event, so a sink added later reads an
// already-redacted line.

// RevlRedactedSecret must equal confidential.REDACTED on the py tier: a
// polyglot composition redacts to the SAME marker whichever tier wrote the line.
const RevlRedactedSecret = "<redacted:secret>"

// A remembered value has to be long enough that an exact match means something.
// Below this it is a coin flip against ordinary trace data ("", "1", "ok"), and
// blanket-erasing those would gut the trace for no confidentiality gain. Same
// bound as the py tier's _MIN_MARKABLE.
const revlMinMarkable = 4

var _revlSecretMu sync.Mutex

// Longest first, so a needle containing another leaves no tail behind.
var _revlSecretValues []string

// revlRenderings is every face one string value wears inside host text (item
// 421 F6(d)).
//
// The match in revlRedactText is EXACT, and the text it runs over has already
// been RENDERED. A value that holds a quote, a backslash or a control character
// comes back ESCAPED from any encoder this tier renders it with — the runner's
// probe channel writes a container with `json.Marshal` before the line reaches
// the funnel, and the seam wire escapes the same way — so the raw bytes match
// nothing there, and a `Secret[Str]` holding such a value crossed verbatim
// while the identical value without the quote was scrubbed everywhere.
// Registering the encoder's body closes that.
//
// Derived from `json.Marshal` itself rather than restating its escape table, so
// the face cannot drift from the encoder that writes it. `encoding/json` quotes
// the result, hence the slice.
func revlRenderings(text string) []string {
	faces := []string{text}
	if encoded, err := json.Marshal(text); err == nil && len(encoded) >= 2 {
		if body := string(encoded[1 : len(encoded)-1]); body != text {
			faces = append(faces, body)
		}
	}
	return faces
}

// revlRememberSecret registers a declared-Secret value (item 421 F6, and the
// F6(e) follow-up below).
//
// Stringifying the value ONCE and registering the faces of that string is the
// whole story for a scalar — `%v` of a string IS the string. It is not the
// whole story for a container. The trace sink renders one with `%v` (`[a b]`),
// while the probe channel, the seam wire and the durable WAL all marshal the
// VALUE, so the same `Secret[List[Str]]` wears `["a","b"]` in the text they
// write and neither the raw face nor the json face of the `%v` string matches
// it: the value crossed verbatim. `Secret[Bytes]` is further apart still, `%v`
// writing `[104 101 …]` where `json.Marshal` writes base64.
//
// The py tier, which defines these semantics, walks a container for exactly
// this reason (`confidential._needles`); `revlRegisterValue` walks it the same
// way and adds the value's OWN json body beside the display form's.
func revlRememberSecret(v any) {
	rv := reflect.ValueOf(v)
	if revlIsContainer(rv) {
		// item 421 F6(e): a container's faces are the ones the loop below cannot
		// derive, because the sinks that matter marshal the value instead of
		// printing it — the json the probe channel, the seam wire and the
		// durable WAL write, and the leaves a host body can interpolate on their
		// own. The walk produces all of them, and it can tell a value that
		// re-enters itself from one that does not. `%v` cannot: `fmt`'s own walk
		// is unbounded, so `fmt.Sprintf("%v", v)` on a self-referential map is a
		// `fatal error: stack overflow` that no `recover` intercepts, and a `@go`
		// body is verbatim go, so `m := map[string]any{}; m["self"] = m` reaches
		// here from admitted source. The walk bounds each rendering it registers
		// on that rendering's own raw text, the bound the py tier applies to each
		// needle.
		revlRegisterValue(rv, map[revlWalkKey]bool{})
		return
	}
	text := fmt.Sprintf("%v", v)
	if len(text) < revlMinMarkable {
		return
	}
	// The bound gates the RAW value only: an escape can only ever expand, so a
	// value that cleared it clears it in every escaped face too.
	for _, face := range revlRenderings(text) {
		revlRegisterFace(face)
	}
}

// revlIsContainer reports whether `%v` of a value is Go's debug rendering
// rather than the value's own text — true for a slice, an array, a map and a
// struct, the shapes whose faces the loop above cannot derive because the
// sinks that matter marshal them instead of printing them.
func revlIsContainer(rv reflect.Value) bool {
	switch rv.Kind() {
	case reflect.Interface, reflect.Pointer:
		if rv.IsNil() {
			return false
		}
		return revlIsContainer(rv.Elem())
	case reflect.Slice, reflect.Array, reflect.Map, reflect.Struct:
		return true
	}
	return false
}

// revlWalkKey identifies one container on the walk, so a value that re-enters
// itself can be recognised. Pointer identity and not equality: two equal-but-
// distinct nodes are two nodes and both have leaves to register, and hashing a
// container to test membership is the work this walk exists to avoid. The walk
// holds the value alive, so its address cannot be recycled underneath it.
type revlWalkKey struct {
	ptr uintptr
	typ reflect.Type
}

// revlWalkKeyOf is the identity of a container, when it has one. Arrays and
// structs are values: they cannot close a cycle by themselves, and every cycle
// through one of them passes through a pointer, a map or a slice. A slice's
// Pointer is the address of its first element, so two windows onto one backing
// array share a key; that is only reachable when one genuinely contains the
// other, which is the cycle the key exists to catch.
func revlWalkKeyOf(rv reflect.Value) (revlWalkKey, bool) {
	switch rv.Kind() {
	case reflect.Pointer, reflect.Map:
		if rv.IsNil() {
			return revlWalkKey{}, false
		}
		return revlWalkKey{rv.Pointer(), rv.Type()}, true
	case reflect.Slice:
		if rv.IsNil() {
			return revlWalkKey{}, false
		}
		return revlWalkKey{rv.Pointer(), rv.Type()}, true
	}
	return revlWalkKey{}, false
}

// revlRegisterValue registers every face of one value and of everything inside
// it. Each rendering is bounded on its own raw text — exactly as the py tier
// bounds each needle — so a container of short leaves contributes no short
// needle.
//
// The walk is bounded by the PATH it is on, not by a depth. The bound used to
// be `depth > 8`, and a depth cap is a confidentiality regression in exactly
// the walk that exists to prevent one: a `Map[Str, Any]` spends two frames per
// level — the map, then the interface holding the next one — so the fourth
// level put its leaf past the cap, the leaf was never registered as its own
// text, and `revlRedactText` left it verbatim in every sink while the composite
// renderings above it matched nothing. A back-edge can only lead to a node the
// walk is already inside, so a path set terminates on a cycle and still reaches
// every leaf of every legal value.
//
// The result says whether the subtree below this node closes a cycle. A cyclic
// container has no finite `%v`, and `fmt`'s own walk is unbounded, so rendering
// one is a `fatal error: stack overflow` that no `recover` can intercept. An
// ANCESTOR of a cycle has the same problem, which is why the flag is propagated
// rather than handled where it is found.
func revlRegisterValue(rv reflect.Value, seen map[revlWalkKey]bool) bool {
	if !rv.IsValid() {
		return false
	}
	switch rv.Kind() {
	case reflect.Interface, reflect.Pointer:
		if rv.IsNil() {
			return false
		}
		if key, ok := revlWalkKeyOf(rv); ok {
			if seen[key] {
				return true
			}
			seen[key] = true
			defer delete(seen, key)
		}
		return revlRegisterValue(rv.Elem(), seen)
	case reflect.Slice:
		if rv.IsNil() {
			return false
		}
		if rv.Type().Elem().Kind() == reflect.Uint8 {
			// Bytes. The decoded text is what a sink that prints the payload
			// writes, and it is the one form `%v` never produces here; the
			// value's own json face below is the base64 the wire carries, so
			// both are registered.
			decoded := make([]byte, 0, rv.Len())
			for i := 0; i < rv.Len(); i++ {
				decoded = append(decoded, byte(rv.Index(i).Uint()))
			}
			revlRegisterText(string(decoded))
			break
		}
		fallthrough
	case reflect.Array:
		if key, ok := revlWalkKeyOf(rv); ok {
			if seen[key] {
				return true
			}
			seen[key] = true
			defer delete(seen, key)
		}
		cyclic := false
		for i := 0; i < rv.Len(); i++ {
			if revlRegisterValue(rv.Index(i), seen) {
				cyclic = true
			}
		}
		if cyclic {
			return true
		}
	case reflect.Map:
		if rv.IsNil() {
			return false
		}
		if key, ok := revlWalkKeyOf(rv); ok {
			if seen[key] {
				return true
			}
			seen[key] = true
			defer delete(seen, key)
		}
		cyclic := false
		iter := rv.MapRange()
		for iter.Next() {
			// The KEYS are registered too. The values-only rule this loop used
			// to carry cited the record rule -- "a record's KEYS are field
			// names the author wrote, not the caller's data" -- but a record is
			// a `reflect.Struct` and takes the branch below, which reads
			// `rv.Field(i)` and so skips its field names by construction. A
			// revl `Map` is not a record: its keys ARE the caller's data, and a
			// key the caller chose is as confidential as the value it maps to.
			if revlRegisterValue(iter.Key(), seen) {
				cyclic = true
			}
			if revlRegisterValue(iter.Value(), seen) {
				cyclic = true
			}
		}
		if cyclic {
			return true
		}
	case reflect.Struct:
		cyclic := false
		for i := 0; i < rv.NumField(); i++ {
			if field := rv.Field(i); field.CanInterface() {
				if revlRegisterValue(field, seen) {
					cyclic = true
				}
			}
		}
		if cyclic {
			return true
		}
	}
	if !rv.CanInterface() {
		return false
	}
	// The display form, which is what a trace line interpolating this value
	// prints...
	revlRegisterText(fmt.Sprintf("%v", rv.Interface()))
	// ...and the value's OWN json body, which is what the probe channel, the
	// seam wire and the durable WAL write. The two differ for a container, and
	// registering only the first is the gap F6(e) closed.
	if encoded, err := json.Marshal(rv.Interface()); err == nil && len(encoded) >= 2 {
		revlRegisterText(string(encoded[1 : len(encoded)-1]))
	}
	return false
}

// revlRegisterText applies the markable bound and registers every face of one
// rendering, the same bound-then-render order as revlRememberSecret.
func revlRegisterText(text string) {
	if len(text) < revlMinMarkable {
		return
	}
	for _, face := range revlRenderings(text) {
		revlRegisterFace(face)
	}
}

// revlRegisterFace adds one face, longest first so a needle containing another
// leaves no tail behind.
func revlRegisterFace(face string) {
	_revlSecretMu.Lock()
	defer _revlSecretMu.Unlock()
	if !slices.Contains(_revlSecretValues, face) {
		_revlSecretValues = append(_revlSecretValues, face)
	}
	slices.SortFunc(_revlSecretValues, func(a, b string) int { return len(b) - len(a) })
}

// revlMarkSecret registers each declared-Secret value (the receiver end).
func revlMarkSecret(values ...any) {
	for _, v := range values {
		revlRememberSecret(v)
	}
}

// revlSecretResult registers a declared-Secret return and hands it back
// unchanged, so a call site wraps with no change in meaning (the origin end).
func revlSecretResult[T any](v T) T {
	revlRememberSecret(v)
	return v
}

// revlRedactText replaces every registered secret in free-form host text.
func revlRedactText(text string) string {
	_revlSecretMu.Lock()
	defer _revlSecretMu.Unlock()
	for _, needle := range _revlSecretValues {
		if needle != "" && strings.Contains(text, needle) {
			text = strings.ReplaceAll(text, needle, RevlRedactedSecret)
		}
	}
	return text
}

// RevlForgetSecrets drops every remembered value (test isolation).
func RevlForgetSecrets() {
	_revlSecretMu.Lock()
	_revlSecretValues = nil
	_revlSecretMu.Unlock()
}

func hostRecord(op string) {
	op = revlRedactText(op)
	_hostMu.Lock()
	_hostLog = append(_hostLog, op)
	_hostMu.Unlock()
}

// HostMarks returns an ordered snapshot of host operations.
func HostMarks() []string {
	_hostMu.Lock()
	defer _hostMu.Unlock()
	out := make([]string, len(_hostLog))
	copy(out, _hostLog)
	return out
}

// HostReset clears the host op log (call between scenarios).
func HostReset() {
	_hostMu.Lock()
	_hostLog = nil
	_hostMu.Unlock()
	RevlForgetSecrets()
}

// Row is a query result row.
type Row = map[string]string

// Pool is a deterministic in-memory connection pool.
type Pool struct {
	url  string
	size int64
}

func PoolOpen(url string, size int64) *Pool {
	hostRecord("pool.open")
	revlHostAcquire()
	return &Pool{url: url, size: size}
}
func (p *Pool) Close() { hostRecord("pool.close"); revlHostRelease() }
func (p *Pool) Query(sql string) []Row {
	hostRecord("pool.query:" + sql)
	return nil
}
func (p *Pool) Execute(sql string) int64 {
	hostRecord("pool.execute:" + sql)
	return 0
}

// Map is a thread-safe map with Str keys. The value type is generic — each
// site's `Map.new()` pins `V` from how the map is used (FR-4: a revl
// `Map[Str, Int]` counter or `Map[Str, List[Msg]]` ledger, not only String),
// mirroring backends/rust/emit.py's `struct Map<V>`. Emit instantiates it at
// the acquisition (`MapNew[int64]()`), so the boundary carries the declared
// value type and Insert/Get type-check against the component's real values.
type Map[V any] struct {
	mu sync.Mutex
	m  map[string]V
}

func MapNew[V any]() *Map[V] {
	hostRecord("map.new")
	revlHostAcquire()
	return &Map[V]{m: map[string]V{}}
}
func (m *Map[V]) Drop() { hostRecord("map.drop"); revlHostRelease() }
func (m *Map[V]) Insert(k string, v V) {
	m.mu.Lock()
	m.m[k] = v
	m.mu.Unlock()
}

// InsertIfAbsent is the atomic compare-and-set (item 397). The per-op mutex is
// held across BOTH the membership test AND the insert, so the whole CAS is one
// critical section: no concurrent caller can witness the probe and the write as
// separable steps. Returns whether it inserted; a false (key already present)
// leaves the existing value untouched. Under N concurrent callers on one map,
// exactly one receives true.
func (m *Map[V]) InsertIfAbsent(k string, v V) bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, ok := m.m[k]; ok {
		return false
	}
	m.m[k] = v
	return true
}
func (m *Map[V]) Remove(k string) {
	m.mu.Lock()
	delete(m.m, k)
	m.mu.Unlock()
}
func (m *Map[V]) Get(k string) (V, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	v, ok := m.m[k]
	return v, ok
}

// Iteration surface (docs/stdlib-2.0.md §Map): the checker promises
// `size()`/`keys()` on a host `Map.new()` receiver too, and emit lowers both
// as method calls on this object. `Size` is the entry count as the tier's
// revl Int (int64, matching the service-method return type); `Keys`
// yields the keys in ascending canonical Str order (UTF-8 byte lexicographic —
// go string < is exactly code-point order, and slices.Sort on []string orders
// by <, so the order is identical to the insertion sort this replaced, as it
// is in revlMapKeys). keys() IS the Map iteration surface, so this sits on
// every map traversal: O(n log n), not O(n^2) (item 434 (h)). Both are
// read-only queries, no host trace — like Get.
func (m *Map[V]) Size() int64 {
	m.mu.Lock()
	defer m.mu.Unlock()
	return int64(len(m.m))
}
func (m *Map[V]) Keys() []string {
	m.mu.Lock()
	ks := make([]string, 0, len(m.m))
	for k := range m.m {
		ks = append(ks, k)
	}
	m.mu.Unlock()
	slices.Sort(ks)
	return ks
}

func mint_token(u string) string {
	return revlSecretResult(revlSecret_mint_token(u))
}

func revlSecret_mint_token(u string) string {
	return "SEKRIT-CANARY"
}

func forget_statement() {
	return
}

// service Vault
type Vault interface {
	Issue(user string) string
	Replay(token string) string
}

var _keyVault = stc.NewKey[Vault]("vault")

func Issuer() stc.Component {
	return stc.Component{
		Name:    "Issuer",
		Provide: []stc.Key{_keyVault},
		Apply: func(ctx *stc.Context) (stc.Inverse, error) {
			var pool *Pool
			if err := ctx.Effect(func() stc.Inverse {
				pool = PoolOpen("pg://main", 2)
				return func() error { pool.Close(); return nil }
			}); err != nil {
				return nil, err
			}
			_implVault := &Issuer_vault{ctx: ctx, pool: pool}
			if _, err := ctx.Provide(_keyVault, Vault(_implVault)); err != nil {
				return nil, err
			}
			_ = pool
			return nil, nil
		},
	}
}

type Issuer_vault struct {
	ctx  *stc.Context
	pool *Pool
}

func (revlSelf *Issuer_vault) Issue(user string) string {
	t := mint_token(user)
	_ = t
	revlSelf.ctx.Effect(func() stc.Inverse {
		revlSelf.pool.Execute(t)
		return func() error { forget_statement(); return nil }
	})
	return "issued"
}

func (revlSelf *Issuer_vault) Replay(token string) string {
	revlMarkSecret(token)
	revlSelf.ctx.Effect(func() stc.Inverse {
		revlSelf.pool.Execute(token)
		return func() error { forget_statement(); return nil }
	})
	return "replayed"
}

func LoadIssuer(target *stc.Context) *stc.Fiber {
	return target.Load(Issuer())
}

// ---- lifecycle tests (docs/syntax-2.0.md §7.1) ----------------
// A `lifecycle test` drives the composition on a live stc-go
// context: load components, call through provision keys, unload
// LIFO, and assert no residue (R4 registry + R1 host resources).
type revlOptPair[T any] struct {
	value T
	ok    bool
}

func revlEq(a, b any) bool { return reflect.DeepEqual(a, b) }

func revlListIndexOfEq[T any](xs []T, x T) int64 {
	for i, v := range xs {
		if revlEq(v, x) {
			return int64(i)
		}
	}
	return -1
}

func TestTheIssuerActivatesAndRevertsItsPool(revlT *testing.T) {
	root := stc.New()
	_fibers := map[string]*stc.Fiber{}
	{
		_f := LoadIssuer(root)
		if err := _f.Ready(stdctx.Background()); err != nil {
			revlT.Fatalf("%s: %v", "lifecycle test \"the issuer activates and reverts its pool\": load Issuer", err)
		}
		_fibers["Issuer"] = _f
	}
	if _f, _ok := _fibers["Issuer"]; _ok {
		_f.Dispose()
		// disposal is orchestrated asynchronously; a
		// reload must not collide with the old fiber's
		// provisions, so wait for it to be Gone
		for i := 0; i < 200 && _f.State() != stc.StateGone; i++ {
			time.Sleep(5 * time.Millisecond)
		}
		delete(_fibers, "Issuer")
	}
	// R4 + R1: the composition must leave the live
	// runtime holding nothing — the orchestrator reaps
	// disposed fibers asynchronously, so poll briefly.
	for i := 0; i < 200; i++ {
		if len(root.Fibers()) == 0 && revlHostLive() == 0 {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	if !(len(root.Fibers()) == 0 && revlHostLive() == 0) {
		revlT.Fatalf("lifecycle test \"the issuer activates and reverts its pool\": residue \u2014 %d fiber(s), %d host resource(s) (R4/R1)", len(root.Fibers()), revlHostLive())
	}
}
